using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.USR.TiposMascota{    [SwaggerSchema("Modelo de lectura de un TiposMascota")]    [GraphQLDescription("Objeto que representa un TiposMascota existente.")]    public class clReadTiposMascota    {        [SwaggerSchema("Identificador único del TiposMascota")]        [GraphQLDescription("Identificador único del TiposMascota")]        public int? TipoMascotaID { get; set; }        [SwaggerSchema("TipoMascota")]        [GraphQLDescription("TipoMascota")]        public string? TipoMascota { get; set; } = default!;        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un TiposMascota")]    [GraphQLDescription("Input para crear un TiposMascota.")]    public class clCreateTiposMascota    {        [GraphQLNonNullType] [SwaggerSchema("TipoMascota")]        [GraphQLDescription("TipoMascota")]        public string TipoMascota { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un TiposMascota")]    [GraphQLDescription("Input para actualizar parcialmente un TiposMascota.")]    public class clUpdateTiposMascota    {        [SwaggerSchema("Identificador único del TiposMascota")]        [GraphQLDescription("Identificador único del TiposMascota")]        public int? TipoMascotaID { get; set; }        [SwaggerSchema("TipoMascota")]        [GraphQLDescription("TipoMascota")]        public string? TipoMascota { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}